actions.script:
// Every dataset this user may query: the telemetry datasets, saved dataset definitions and the DataDocument indexes.
const telemetry = ['otel_spans','otel_logs','otel_metrics','otel_errors','monitor_annotations']
datasetList = (ec.service.sync().name('org.moqui.report.ReportServices.list#Datasets').call().datasets || []).map(dataset => Object.assign({}, dataset, {
    title: dataset.title || dataset.id,
    kind: telemetry.includes(dataset.id) ? 'Telemetry' : String(dataset.id).startsWith('index:') ? 'Document index' : 'Saved dataset',
    saved: !telemetry.includes(dataset.id) && !String(dataset.id).startsWith('index:')
}))
fieldList = []; fieldNotice = ''; selectedTimeField = ''
if (datasetId) {
    try {
        const dataset = ec.service.sync().name('org.moqui.report.ReportServices.get#Dataset').parameters({datasetId}).call().dataset || {}
        fieldList = (dataset.fields || []).map(field => ({name:field.name,type:field.type,kind:field.kind || '',
            searchable:field.searchable === false ? 'N' : 'Y',aggregatable:field.aggregatable ? 'Y' : 'N'}))
        selectedTimeField = dataset.timeField || ''
    } catch (error) { ec.logger.error('Dataset '+datasetId+' fields unavailable: '+String(error)); fieldNotice = String(error) }
}
